// What the workers call. Picks the fast path when it applies and falls back to the
// readable implementation when it does not.
//
// Both files come from https://github.com/Peergos/blake3 (../../../blake3 locally):
// blake3-fast.js is generated by its tools/gen-fast.py --ship and must not be edited
// here, and neither may be generated at load time - runtime code generation would need
// 'unsafe-eval' in the CSP, which is the thing shipping pure JS exists to avoid.

import * as fast from './blake3-fast.js';
import * as ref from './blake3.js';

const CHUNK_LEN = 1024;

/** The BLAKE3 hash of a whole input: the bytes b3sum prints. Used for a one chunk file. */
export function hash(bytes) {
    return ref.hash(bytes);
}

/**
 * The chaining value of one chunk of a file, for merging into the file's root.
 *
 * The fast path only handles a whole, aligned, power-of-two run of chunks, which is what
 * every chunk of a file except the last one is. The last chunk is short, so it goes the
 * slow way - once per file, over at most one chunk's worth of bytes.
 */
export function chainingValue(bytes, startChunk) {
    const chunks = bytes.length / CHUNK_LEN;
    if (Number.isInteger(chunks) && chunks >= 1 && (chunks & (chunks - 1)) === 0
        && startChunk % chunks === 0 && fast.LITTLE_ENDIAN && (bytes.byteOffset & 3) === 0)
        return fast.subtreeCV(bytes, startChunk);
    return ref.tailCV(bytes, startChunk);
}

export const mergeNonRoot = fast.mergeNonRoot;
export const mergeRoot = fast.mergeRoot;
